package com.aegis.erp.modules.seguridad.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import com.aegis.erp.common.exception.DatabaseUnavailableException; import com.aegis.erp.common.response.DatabaseHealthResponse; import java.sql.ResultSet; import org.junit.jupiter.api.Test; import org.springframework.dao.DataAccessResourceFailureException; import org.springframework.jdbc.core.*;
class DatabaseHealthServiceTest {JdbcTemplate jdbc=mock(JdbcTemplate.class); DatabaseHealthService service=new DatabaseHealthService(jdbc); @Test @SuppressWarnings("unchecked") void readsOracleValues()throws Exception{ResultSet rs=mock(ResultSet.class);when(rs.getString("SCHEMA_NAME")).thenReturn("AEGIS_ERP");when(rs.getString("CONTAINER_NAME")).thenReturn("XEPDB1");when(jdbc.queryForObject(anyString(),any(RowMapper.class))).thenAnswer(i->i.<RowMapper<DatabaseHealthResponse>>getArgument(1).mapRow(rs,0));assertThat(service.check()).isEqualTo(new DatabaseHealthResponse("UP","Oracle","AEGIS_ERP","XEPDB1"));} @Test @SuppressWarnings("unchecked") void handlesFailure(){when(jdbc.queryForObject(anyString(),any(RowMapper.class))).thenThrow(new DataAccessResourceFailureException("secret"));assertThatThrownBy(service::check).isInstanceOf(DatabaseUnavailableException.class);}}
